  ('0bf2a89b-4ada-4272-a3f5-861763fa251b', 'b8c9d0e1-2f3a-4b38-9c78-8d9e0f1a2b98', null, 'topic'::public.curated_course_node_type, 'Business Strategy and HR Alignment', 'This section establishes strategic HRM as the discipline of aligning people systems with organizational direction. Students learn to translate competitive strategy into workforce priorities, HR capabilities, and measurable execution plans.', 0),
