  'Strategic Human Resource Management',
  'This course prepares senior undergraduate human resources students to design HR systems that create strategic value. Students examine business strategy and HR alignment, human capital advantage, workforce architecture, talent segmentation, culture and change, restructuring, global HR, DEI strategy, scorecards, strategic case analysis, people analytics, AI-enabled HR, governance, ethics, and stakeholder value.',
  $shrmjson${"slug": "strategic-human-resource-management", "title": "Strategic Human Resource Management", "description": "This course prepares senior undergraduate human resources students to design HR systems that create strategic value. Students examine business strategy and HR alignment, human capital advantage, workforce architecture, talent segmentation, culture and change, restructuring, global HR, DEI strategy, scorecards, strategic case analysis, people analytics, AI-enabled HR, governance, ethics, and stakeholder value.", "topics": [{"id": "0bf2a89b-4ada-4272-a3f5-861763fa251b", "type": "topic", "title": "Business Strategy and HR Alignment", "description": "This section establishes strategic HRM as the discipline of aligning people systems with organizational direction. Students learn to translate competitive strategy into workforce priorities, HR capabilities, and measurable execution plans.", "children": [{"id": "c508c759-8b7a-4e6e-9a51-5ee009a0b287", "type": "subtopic", "title": "Business strategy foundations", "children": [{"id": "b5c254fe-96da-4c68-96ad-5136094ebefa", "type": "concept", "title": "Competitive advantage and value proposition"}, {"id": "a5b9c21f-d336-4791-9a26-e3d4df3fe7ab", "type": "concept", "title": "Cost leadership, differentiation, focus, and platform strategies"}, {"id": "0df576e3-57b7-4718-a0be-55ad174dbbfb", "type": "concept", "title": "Industry forces, customers, and operating model"}], "description": "The point is to understand the business model before recommending HR interventions."}, {"id": "1c143998-6ce4-4365-a5bc-b6e2d098d492", "type": "subtopic", "title": "Vertical and horizontal HR alignment", "children": [{"id": "9d42b6c4-ec68-4401-abab-830cbcc51ee6", "type": "concept", "title": "Vertical fit with strategy"}, {"id": "dc3a1158-c789-46ac-a25d-f8bf01bf1a0c", "type": "concept", "title": "Horizontal fit among staffing, rewards, development, and performance systems"}, {"id": "d9703b83-f693-4964-a56f-56159912bc12", "type": "concept", "title": "Internal consistency and tradeoffs"}], "description": "Students learn to align HR with business strategy and to align HR practices with one another."}, {"id": "e95ec0dc-f71e-4f51-b8ab-9973490b4a2c", "type": "subtopic", "title": "HR as strategic partner", "children": [{"id": "9eade5e6-d61e-4632-b9e5-ffbbb65236c1", "type": "concept", "title": "Business literacy"}, {"id": "5c60332d-1a16-47a8-997f-4fc5df218030", "type": "concept", "title": "Consulting mindset"}, {"id": "78335c89-ace6-4d7f-b9ee-115e4e0e9502", "type": "concept", "title": "Influence with leaders and line managers"}], "description": "This subtopic reframes HR from administrative service to strategic value creator."}, {"id": "36c89915-166d-4d48-8bc8-7ec75e069a7e", "type": "subtopic", "title": "Strategy execution through people", "children": [{"id": "86bedee4-481a-4882-a7f0-d2497881afe5", "type": "concept", "title": "Critical roles and capabilities"}, {"id": "e1fe10b6-8e1e-432c-a61a-93bcd5075dd8", "type": "concept", "title": "Change adoption"}, {"id": "8b6bbcda-1080-4b7a-98ea-f9f3845bef79", "type": "concept", "title": "Leadership accountability and governance"}], "description": "Students learn how workforce practices make strategic choices real."}]}, {"id": "f09cbd54-9b96-420f-ad4a-0cd2f694b6a7", "type": "topic", "title": "Human Capital Advantage", "description": "Human capital advantage focuses on how people, skills, relationships, motivation, and culture create value that competitors cannot easily copy. Students learn to evaluate workforce capability as a strategic asset.", "children": [{"id": "bade32dd-cd24-4185-9f7e-73ed174bf928", "type": "subtopic", "title": "Human capital theory", "children": [{"id": "4ae49771-0cae-4b53-82c1-940d4a0537ee", "type": "concept", "title": "Firm-specific skills"}, {"id": "354791a3-1e1e-47eb-825f-53a809595d70", "type": "concept", "title": "Social and relational capital"}, {"id": "f74cff14-6a7c-4e99-80c4-5ba2594296de", "type": "concept", "title": "Tacit knowledge and learning curves"}], "description": "Students learn why knowledge, skills, abilities, and relationships can become sources of advantage."}, {"id": "e523e0f6-5e1f-42ac-a2e0-5ff6b99db914", "type": "subtopic", "title": "Resource-based view of the firm", "children": [{"id": "04edda13-74f1-4fb4-a53d-404c4cbffe47", "type": "concept", "title": "VRIO analysis"}, {"id": "4912b6e5-5969-43c8-b5bb-9c845dfbfdb6", "type": "concept", "title": "Strategic capabilities"}, {"id": "04862b5f-a720-4fe2-a84e-3e4150b71119", "type": "concept", "title": "Imitability and path dependence"}], "description": "The gist is to assess whether workforce capabilities are valuable, rare, hard to imitate, and organized for use."}, {"id": "4fd3fc0d-fbeb-4c03-b390-ac220af024af", "type": "subtopic", "title": "Employee value creation", "children": [{"id": "0b7f0e42-8e00-4332-9a57-f482f5e4ef37", "type": "concept", "title": "Productivity and innovation"}, {"id": "5e3f72e3-d381-47da-a606-bf2196a5d6e2", "type": "concept", "title": "Service quality and customer experience"}, {"id": "c8571056-03dd-4115-affb-561c5193bb30", "type": "concept", "title": "Risk reduction and resilience"}], "description": "Students connect workforce behavior to customer, operational, financial, and social outcomes."}, {"id": "67206291-e002-43cd-8c66-2069a69c3876", "type": "subtopic", "title": "Sustaining advantage", "children": [{"id": "f5a93781-bfd8-43fa-a61b-02b1e1ed59a7", "type": "concept", "title": "Retention of critical talent"}, {"id": "3179f3ed-f812-4b5c-b3f7-73494b6eece1", "type": "concept", "title": "Knowledge transfer"}, {"id": "e3a4d959-701c-428e-b9d4-ea0b03184376", "type": "concept", "title": "Learning agility and capability renewal"}], "description": "This subtopic asks how HR systems preserve and renew talent advantage."}]}, {"id": "3c874c9b-fca1-4887-875f-42932d191231", "type": "topic", "title": "Workforce Architecture", "description": "Workforce architecture is the design of roles, employment relationships, skills, career paths, and work systems. Students learn to structure the workforce so talent investments match strategic contribution.", "children": [{"id": "bc6c3d6d-b813-436f-a441-dbe2422c3fe0", "type": "subtopic", "title": "Role and capability mapping", "children": [{"id": "7acccada-759c-49e4-95a5-20071e5d1a30", "type": "concept", "title": "Critical roles"}, {"id": "325dc8e1-e047-40b7-8eaf-215c0dc4c067", "type": "concept", "title": "Skill inventories"}, {"id": "5a471413-73f6-4e94-a77e-ff6551e16d18", "type": "concept", "title": "Capability gaps and future needs"}], "description": "Students learn to identify which roles and capabilities matter most for strategic success."}, {"id": "61e85fd8-10d5-454f-9855-550b0ff50467", "type": "subtopic", "title": "Employment relationship design", "children": [{"id": "8769b652-4daf-416f-afb2-bdcbf753ad56", "type": "concept", "title": "Core employees, contingent workers, contractors, platforms, and partners"}, {"id": "2586a787-4591-43fa-875d-ca5889620e13", "type": "concept", "title": "Build, buy, borrow, bot, and bind decisions"}, {"id": "045d55a0-686e-480d-ab2b-1d34c28e1c38", "type": "concept", "title": "Risk and dependency tradeoffs"}], "description": "The point is to choose workforce arrangements intentionally."}, {"id": "22791078-86ce-4c8c-b43d-bfc44354774d", "type": "subtopic", "title": "Skills-based organization", "children": [{"id": "44aa9d54-f61c-4a38-8b24-4a74a0384a8f", "type": "concept", "title": "Skills taxonomies"}, {"id": "6e1fe772-8b9a-4a1d-9c3c-b690be8e3560", "type": "concept", "title": "Internal talent marketplaces"}, {"id": "0dd4d9c8-95bb-499b-8976-eb9675bd3011", "type": "concept", "title": "Career pathways and reskilling"}], "description": "Students learn how organizations shift from job-only thinking to skills-based talent mobility."}, {"id": "7941fcf3-030a-4c07-8a48-44da5bffe5b5", "type": "subtopic", "title": "Organization design interface", "children": [{"id": "d029f34b-04aa-4cc3-bc06-065c94ed7022", "type": "concept", "title": "Centralization and decentralization"}, {"id": "778743be-afca-4708-885d-4d0536b63ff5", "type": "concept", "title": "Spans, layers, and agile teams"}, {"id": "288ee076-883f-494c-b374-11efdb43d34a", "type": "concept", "title": "Role clarity and accountability"}], "description": "This subtopic connects workforce architecture to structure and decision rights."}]}, {"id": "36cfddc4-94e8-4dc2-90b4-6331bcacd0e5", "type": "topic", "title": "Talent Segmentation", "description": "Talent segmentation helps HR avoid one-size-fits-all systems. Students learn to differentiate talent investments by strategic value, scarcity, risk, and employee experience while preserving fairness and legal defensibility.", "children": [{"id": "d6587d63-01c2-4198-959f-46d3e2b6ad3e", "type": "subtopic", "title": "Segmentation logic", "children": [{"id": "a9a3a148-2886-454d-ae7e-026124fbfb70", "type": "concept", "title": "Strategic value and role impact"}, {"id": "c682f585-e0e4-48c2-b80a-4261afc2b86a", "type": "concept", "title": "Talent scarcity"}, {"id": "cd598a71-79b5-4f78-bb22-35c95aca151c", "type": "concept", "title": "Performance variability and risk"}], "description": "Students learn why different roles and talent groups may need different HR strategies."}, {"id": "1657fbed-e3eb-4e70-a350-fc07fe8ca634", "type": "subtopic", "title": "Differentiated talent investments", "children": [{"id": "7fabdfe3-4dc1-46d8-8449-26b6f0d22e45", "type": "concept", "title": "High-potential programs"}, {"id": "faba8f81-da4d-4d18-be31-e4c6adadb13a", "type": "concept", "title": "Critical skill development"}, {"id": "22919dbf-d1c2-430e-b3d8-957ed1864a46", "type": "concept", "title": "Retention and succession priorities"}], "description": "The gist is to allocate scarce resources where they create the most value."}, {"id": "67844855-6285-4bc4-a6a7-0be7b8802826", "type": "subtopic", "title": "Employee experience segmentation", "children": [{"id": "2c44369a-30d3-4412-abd8-6e5fe3061e18", "type": "concept", "title": "Personas and journey mapping"}, {"id": "e00ea570-f614-4682-aead-20963160a19b", "type": "concept", "title": "Flexibility and wellbeing needs"}, {"id": "cb5b921e-a1cb-4809-b95e-5555405a8953", "type": "concept", "title": "Inclusion and accessibility considerations"}], "description": "Students learn to understand workforce needs across life stages, roles, and work arrangements."}, {"id": "0230da2e-d8d5-4bde-b156-b299c7ef5b74", "type": "subtopic", "title": "Fairness and transparency", "children": [{"id": "d9e94c15-12a7-4279-a7cc-f36f99c44997", "type": "concept", "title": "Legal and ethical review"}, {"id": "c31fa8be-ee69-4ad9-8180-682b2bb0340b", "type": "concept", "title": "Clear criteria"}, {"id": "8c35c1c7-15c2-4bc6-8f71-80e93005be8f", "type": "concept", "title": "Communication and trust"}], "description": "This subtopic guards against segmentation becoming favoritism or discrimination."}]}, {"id": "e72e7d8a-7406-4347-ac8d-c7e74666956f", "type": "topic", "title": "Culture and Change", "description": "Culture and change are central to strategy execution. Students learn how norms, leadership behavior, symbols, incentives, and systems shape whether employees can and will adopt new strategic priorities.", "children": [{"id": "f6586ab3-c56a-4e5f-b0c3-e34394b48fbf", "type": "subtopic", "title": "Culture diagnosis", "children": [{"id": "73eb3399-e10e-40a9-8f4f-bfd7379f0276", "type": "concept", "title": "Artifacts, values, assumptions, and rituals"}, {"id": "97a681a7-7866-4596-95fd-aee4a7d85c21", "type": "concept", "title": "Employee listening and surveys"}, {"id": "d7751244-31eb-48d7-abdb-a4a843440b26", "type": "concept", "title": "Subcultures and informal networks"}], "description": "Students learn to identify the current culture before trying to change it."}, {"id": "12bec757-9edf-4fd7-8b7a-ffc431ddf21a", "type": "subtopic", "title": "Culture-strategy fit", "children": [{"id": "6cdaef8c-c224-4e4c-8eea-0da152b345c8", "type": "concept", "title": "Innovation, service, safety, compliance, and performance cultures"}, {"id": "5d997ba5-f125-4cd7-a4b7-b3000fab2f96", "type": "concept", "title": "Behavioral norms and incentives"}, {"id": "8392a61d-21ae-4739-a0b8-45d50b300d52", "type": "concept", "title": "Leadership signals"}], "description": "The point is to assess whether culture enables or blocks strategic goals."}, {"id": "bfefc0d6-dfbc-427f-8647-8cfcaa785a8b", "type": "subtopic", "title": "Change management", "children": [{"id": "7f579b5d-9cd2-44bf-b4e4-a4c97082b654", "type": "concept", "title": "Stakeholder analysis"}, {"id": "2ffad3d8-5fd5-48f6-a2f6-aaafe4f5213c", "type": "concept", "title": "Communication and involvement"}, {"id": "ff33e7dc-cd07-43a0-b030-c934d6db4945", "type": "concept", "title": "Resistance, readiness, and adoption"}], "description": "Students learn structured ways to move people through strategic change."}, {"id": "d8277e4f-b212-4a7a-8d3a-984c49635aaa", "type": "subtopic", "title": "Sustaining change", "children": [{"id": "d05da82e-fc07-40a5-8a2e-c24fa54e19ab", "type": "concept", "title": "Reinforcement through rewards and performance management"}, {"id": "1a59b797-8d87-4828-b0b1-cefd1254f913", "type": "concept", "title": "Manager routines"}, {"id": "457f58a4-6d09-41fb-a81f-58bc16176922", "type": "concept", "title": "Measurement and course correction"}], "description": "This subtopic focuses on embedding change into systems."}]}, {"id": "abf6b150-7d24-480c-af77-f1161a8f806e", "type": "topic", "title": "Mergers and Restructuring", "description": "Mergers, acquisitions, restructuring, and downsizing put HR at the center of strategy, risk, communication, and employee trust. Students learn how people decisions affect deal value and organizational recovery.", "children": [{"id": "2a8bae52-38b4-487f-af78-a1cc6399b7a0", "type": "subtopic", "title": "HR due diligence", "children": [{"id": "1791a766-5700-4b8d-b9df-bc8edc17d300", "type": "concept", "title": "Talent inventory and leadership depth"}, {"id": "c93f9f67-7310-4b09-b70f-dab6c5a1befd", "type": "concept", "title": "Compensation, benefits, and labor obligations"}, {"id": "09b07f2c-697d-4573-9c25-1ba64ae13c36", "type": "concept", "title": "Culture and retention risks"}], "description": "Students learn to examine workforce risk and value before major transactions."}, {"id": "c28350fa-c8f6-499c-b05a-acc650b00f03", "type": "subtopic", "title": "Integration planning", "children": [{"id": "0567301f-a143-42d0-82a5-b032082da00e", "type": "concept", "title": "Operating model integration"}, {"id": "6556a90f-f6f2-4ed4-923f-489026351da9", "type": "concept", "title": "HR systems harmonization"}, {"id": "9f1dd6b2-bc76-4430-94b2-1210bfdc718f", "type": "concept", "title": "Retention and communication plans"}], "description": "The gist is to combine organizations without destroying capability or trust."}, {"id": "3c4bd923-366e-4857-b9cf-dd55e407451f", "type": "subtopic", "title": "Restructuring and workforce reductions", "children": [{"id": "be0c602b-fc28-4655-9cc4-2be1e69e4681", "type": "concept", "title": "Selection criteria"}, {"id": "4d37a82c-cd60-4571-9899-c62134510a65", "type": "concept", "title": "WARN, severance, and legal review"}, {"id": "35f8a932-78de-41eb-b3d7-d7dba5a5580d", "type": "concept", "title": "Survivor engagement and workload"}], "description": "Students learn the strategic, ethical, and legal dimensions of role redesign and layoffs."}, {"id": "81930445-7ad7-4453-9a5d-66a43be1e5d9", "type": "subtopic", "title": "Post-change stabilization", "children": [{"id": "831bd392-bd8a-4966-bca7-b128f7cd84fc", "type": "concept", "title": "New roles and decision rights"}, {"id": "710d9e82-9712-4a9c-b029-9902d8c02c82", "type": "concept", "title": "Culture repair"}, {"id": "f37c21bd-ff9d-4bc9-bf1b-a507090b6343", "type": "concept", "title": "Productivity and engagement recovery"}], "description": "This subtopic focuses on rebuilding performance after disruption."}]}, {"id": "8a1cb603-1ea2-4b99-9e03-2d0fc06ceaca", "type": "topic", "title": "Global HR", "description": "Global HR requires balancing enterprise consistency with local law, labor markets, culture, and employee expectations. Students learn how global people strategy adapts across borders without losing coherence.", "children": [{"id": "eaaf4df4-57a4-40ca-b78a-83c1892143a1", "type": "subtopic", "title": "Global staffing and mobility", "children": [{"id": "36986507-fea5-4f30-9975-c6f0cf551282", "type": "concept", "title": "Expatriates, inpatriates, local nationals, and global teams"}, {"id": "958eaca0-3ecd-4c4b-ad33-4d626072cc7b", "type": "concept", "title": "Immigration and relocation"}, {"id": "71fd4334-2c90-466d-a6c7-9cdad61f0ac2", "type": "concept", "title": "Global leadership pipelines"}], "description": "Students learn how firms deploy talent internationally."}, {"id": "e42c0951-1f4f-43a7-90e5-5bcb3e3516fe", "type": "subtopic", "title": "Comparative employment systems", "children": [{"id": "613f09d8-3c86-473c-828d-b2d12ab35842", "type": "concept", "title": "Labor law and worker voice"}, {"id": "c4ae77c8-c8cb-466b-9af7-935c49c1c8c1", "type": "concept", "title": "Benefits and social insurance"}, {"id": "258a871c-c02b-4671-a7c0-492ffba25458", "type": "concept", "title": "Education systems and labor markets"}], "description": "The point is to understand how national institutions shape HR choices."}, {"id": "8b37dcd6-8d2d-4ef4-89a4-18c86f57aab6", "type": "subtopic", "title": "Cross-cultural management", "children": [{"id": "05032ce2-2c98-42b1-a810-d475d6ec55f8", "type": "concept", "title": "Communication norms"}, {"id": "a664d88e-cb51-4f7b-b0e3-3e97ad2b3d20", "type": "concept", "title": "Power distance and decision making"}, {"id": "de3b9ebe-9529-4bab-aac9-587c17b782fe", "type": "concept", "title": "Inclusive global collaboration"}], "description": "Students learn to work across cultural expectations without stereotyping."}, {"id": "39537135-e2f5-4b95-9a04-d7596ca5d7b8", "type": "subtopic", "title": "Global consistency versus localization", "children": [{"id": "27f8b620-4283-432e-8622-75fb9a31f398", "type": "concept", "title": "Global HR policies"}, {"id": "155176f1-c6c6-4228-ba17-68ae2e94f1e9", "type": "concept", "title": "Local compliance"}, {"id": "b7feab4d-d575-4dce-9b12-980a5f675501", "type": "concept", "title": "Regional centers of excellence"}], "description": "This subtopic helps students decide what should be standardized and what must adapt."}]}, {"id": "d2a979a6-e9ba-4ef4-bebd-15ff03ca9adb", "type": "topic", "title": "DEI Strategy", "description": "DEI strategy connects diversity, equity, inclusion, belonging, and accessibility to business performance, employee dignity, and legal compliance. Students learn to design DEI as a strategic system rather than an isolated initiative.", "children": [{"id": "84f4db1e-c25f-4d7d-8946-d75a4338dbd8", "type": "subtopic", "title": "DEI diagnosis", "children": [{"id": "2ad153cd-da12-4a5c-be10-93caaf5921f7", "type": "concept", "title": "Representation and flow metrics"}, {"id": "10ab2b24-ed0a-4ce6-b8eb-ce05722cf165", "type": "concept", "title": "Pay equity and promotion equity"}, {"id": "0219ff49-ffe2-4a0c-8794-bed50db68395", "type": "concept", "title": "Climate, belonging, and psychological safety"}], "description": "Students learn to identify inequities and barriers using data and employee voice."}, {"id": "e5ebe4f5-694a-407a-8a20-0c7d666ec68d", "type": "subtopic", "title": "Inclusive talent systems", "children": [{"id": "31a01b11-8e6f-4578-8429-ed02a9f298f6", "type": "concept", "title": "Recruiting and selection"}, {"id": "cf6f2e14-8158-4616-b4f2-731308cf1c02", "type": "concept", "title": "Performance and promotion"}, {"id": "d8f72247-1d76-4710-a352-1644ba6dedc2", "type": "concept", "title": "Development, sponsorship, and succession"}], "description": "The gist is to embed equity into core HR practices."}, {"id": "bb875c74-9719-474e-8334-2bebc49e7b73", "type": "subtopic", "title": "Accountability and governance", "children": [{"id": "fb57b745-c1ea-4b28-b946-29238fad086e", "type": "concept", "title": "Executive ownership"}, {"id": "c3e0434b-15b4-4f8e-9e2c-8e0878a669c6", "type": "concept", "title": "Manager accountability"}, {"id": "0c6d0f38-3d89-4edb-85e4-981818aebbb2", "type": "concept", "title": "Employee resource groups and councils"}], "description": "Students learn how DEI work is sustained through roles, goals, and leadership routines."}, {"id": "3bb3e6e1-906b-41e7-9b6f-047643d51187", "type": "subtopic", "title": "Backlash, risk, and communication", "children": [{"id": "2615529e-c218-4b0d-b31c-b8f2dfe5049b", "type": "concept", "title": "Legal context"}, {"id": "bce0a392-c5ae-4bbe-bb0a-96612cea5708", "type": "concept", "title": "Transparent rationale"}, {"id": "1140ec25-524c-461d-836f-541b44ccd9bb", "type": "concept", "title": "Evidence-based and values-based messaging"}], "description": "This subtopic prepares students to handle complexity and maintain trust."}]}, {"id": "39517dbe-5b5d-4df0-a25f-8cadacd891a9", "type": "topic", "title": "HR Scorecards", "description": "HR scorecards translate people strategy into measurable value. Students learn to move beyond activity metrics toward leading and lagging indicators that show whether HR systems support strategic outcomes.", "children": [{"id": "6c1d66c6-284c-4226-8a42-0963319dde38", "type": "subtopic", "title": "Measurement strategy", "children": [{"id": "044a9b2f-4d1c-4d75-b660-655b72ef3428", "type": "concept", "title": "Strategic objectives"}, {"id": "359c1c3c-15a2-490c-8099-54e616e6f28f", "type": "concept", "title": "Leading and lagging indicators"}, {"id": "25cb9cfa-2ebc-4fd9-8bf1-3773e9c313db", "type": "concept", "title": "Activity, efficiency, effectiveness, and impact metrics"}], "description": "Students learn to choose metrics tied to business and workforce outcomes."}, {"id": "3e4c33eb-1cde-425c-8743-12be582eca37", "type": "subtopic", "title": "HR value chain", "children": [{"id": "49567460-3753-44cc-83b0-34fefc19aedf", "type": "concept", "title": "HR deliverables"}, {"id": "14776017-229b-4de2-93c7-984523776962", "type": "concept", "title": "Employee capabilities and behaviors"}, {"id": "a6e5b08d-9eed-4709-8495-750036cbab8e", "type": "concept", "title": "Customer, operational, and financial results"}], "description": "The point is to connect HR practices to workforce behavior and organizational performance."}, {"id": "e759471b-8d03-46a4-8387-ca496f04f256", "type": "subtopic", "title": "Dashboard design", "children": [{"id": "13b367d9-aecc-4d61-9fd2-4ed8097dd160", "type": "concept", "title": "Metric definitions"}, {"id": "6454ad94-72dc-4100-a1ed-e0ee277d9710", "type": "concept", "title": "Visualization and storytelling"}, {"id": "88df6374-5409-4262-8d18-d982909743a4", "type": "concept", "title": "Cadence, owners, and actions"}], "description": "Students learn to make people data usable for decision makers."}, {"id": "cf4959c5-9a1f-487d-b93a-9f00c5bb3478", "type": "subtopic", "title": "Metric risks and ethics", "children": [{"id": "d9de92eb-7281-4ec2-b211-31f10a099265", "type": "concept", "title": "Privacy and data minimization"}, {"id": "3c102621-7870-4171-a706-c83bf93ac5a4", "type": "concept", "title": "Gaming and perverse incentives"}, {"id": "936af749-618e-4ecf-a38e-fbbc58d79f26", "type": "concept", "title": "Equity and subgroup analysis"}], "description": "This subtopic keeps measurement responsible."}]}, {"id": "121cd016-8263-4411-981f-d6662239f55b", "type": "topic", "title": "Strategic HR Case", "description": "The strategic HR case integrates the course. Students learn to diagnose a business problem, identify people-system causes, recommend aligned HR interventions, and defend expected outcomes.", "children": [{"id": "bdfa47b0-b596-4d3e-8d51-9267cd8cb61c", "type": "subtopic", "title": "Case diagnosis", "children": [{"id": "6883abde-37ff-4a32-b5d3-f170138f2bf7", "type": "concept", "title": "Business context"}, {"id": "76c3d0cd-a883-4105-b5dc-94fe70d9eaeb", "type": "concept", "title": "Stakeholders and constraints"}, {"id": "8fa9ead8-1966-4305-bd0a-a464628437cd", "type": "concept", "title": "People-system diagnosis"}], "description": "Students learn to separate symptoms from root causes."}, {"id": "2476f480-6ba5-44c3-8d3c-ed5befdc219e", "type": "subtopic", "title": "Strategic recommendation", "children": [{"id": "6e730a20-4f33-4a66-9154-5d81bafa9159", "type": "concept", "title": "Staffing, development, rewards, culture, and structure interventions"}, {"id": "9bb497a4-94c7-4f76-9332-964ed2288262", "type": "concept", "title": "Prioritization and tradeoffs"}, {"id": "41dbc939-01d1-49de-9d32-e0891ef1eb88", "type": "concept", "title": "Risk and implementation barriers"}], "description": "The gist is to design HR actions that fit the strategy and reinforce one another."}, {"id": "370b57e4-b2ce-42ca-a3d7-f1aa3485f6f7", "type": "subtopic", "title": "Implementation plan", "children": [{"id": "d208e7f7-d16a-4370-be67-fa1a5a5084a9", "type": "concept", "title": "Timeline and milestones"}, {"id": "82f80886-b579-4ad1-bf61-393f5c119600", "type": "concept", "title": "Owners and governance"}, {"id": "f036b688-b0f0-41ad-860e-727f27c887bd", "type": "concept", "title": "Communication and change management"}], "description": "Students learn to translate recommendations into staged action."}, {"id": "e20559c2-72c9-4f7a-96a5-ff7754e03d7f", "type": "subtopic", "title": "Executive presentation", "children": [{"id": "842c32a3-ac9f-4c36-8e4b-019dfe855f30", "type": "concept", "title": "Business case"}, {"id": "2c76ac58-151c-459a-bf93-0aa15a55a0f8", "type": "concept", "title": "Evidence and assumptions"}, {"id": "f2bec6aa-cd46-41bd-9fec-eab3968fe0b4", "type": "concept", "title": "Metrics, expected impact, and next steps"}], "description": "This subtopic prepares students to communicate like strategic HR partners."}]}, {"id": "ea09eaf6-d9a1-4411-9f31-08067bdb7673", "type": "topic", "title": "People Analytics, AI, and Evidence-Based HR", "description": "Students learn to use people analytics, AI-enabled tools, and evidence-based reasoning to improve workforce decisions while managing bias, privacy, and validity risks.", "children": [{"id": "77b6c94c-712f-48a4-b80a-e7770a5b60f1", "type": "subtopic", "title": "Evidence-based HR", "children": [{"id": "945c786a-71d0-46e8-9e55-1f59b8e3d8a4", "type": "concept", "title": "Hierarchy and quality of evidence"}, {"id": "51dfa13a-b794-44c1-945c-d016c418aad1", "type": "concept", "title": "Asking answerable HR questions"}, {"id": "a7311e1f-3d40-44a7-9290-1344356a9562", "type": "concept", "title": "Evidence-to-action translation"}], "description": "Students learn to integrate research evidence, organizational data, professional expertise, and stakeholder values."}, {"id": "4f80d2e5-3433-4674-9d6e-360ba555a8ce", "type": "subtopic", "title": "People analytics methods", "children": [{"id": "b7386791-f0fd-4752-b150-f44700d716cb", "type": "concept", "title": "Descriptive, diagnostic, predictive, and prescriptive analytics"}, {"id": "d23d60d9-cf64-45f6-b0ae-daeb9b7d20df", "type": "concept", "title": "Turnover, engagement, performance, and workforce planning models"}, {"id": "6ec641d8-c810-49d7-ba4a-cb7e807ae734", "type": "concept", "title": "Correlation, causation, and confounding"}], "description": "The point is to understand what analyses can and cannot tell HR leaders."}, {"id": "eb30def6-3550-4b47-a1d8-d8880507fa3c", "type": "subtopic", "title": "AI in HR strategy", "children": [{"id": "c702c432-a7bb-4498-b629-7cf9f0c87883", "type": "concept", "title": "Algorithmic screening and matching"}, {"id": "bebee52d-657e-431d-b4bc-e059b3addcb1", "type": "concept", "title": "Skills inference and talent marketplaces"}, {"id": "7e8740bb-1bf8-4b7e-8438-39121815c455", "type": "concept", "title": "Human oversight and explainability"}], "description": "Students learn to evaluate AI tools in recruiting, learning, performance, and workforce planning."}, {"id": "530ce084-c3b6-4365-8869-f53bffa52ee3", "type": "subtopic", "title": "Responsible data governance", "children": [{"id": "9af4678c-eede-4106-b538-5de9c03edabf", "type": "concept", "title": "Privacy, consent, and security"}, {"id": "7acbd8a2-b950-4277-9b37-44edc4295af9", "type": "concept", "title": "Bias audits"}, {"id": "40b0a399-14f7-4e99-9387-a78999c8ebd5", "type": "concept", "title": "Legal and ethical review"}], "description": "This subtopic protects employees and organizations."}]}, {"id": "c9a0e954-d2a9-4113-95e5-4f26b6523977", "type": "topic", "title": "Governance, Ethics, and Stakeholder Value", "description": "Students learn how HR decisions affect employees, shareholders, customers, communities, regulators, and long-term organizational legitimacy.", "children": [{"id": "2d590581-46e2-4917-a314-af2b8cc724d1", "type": "subtopic", "title": "HR governance and decision rights", "children": [{"id": "b2d76dab-e0e0-4d84-ad07-49aadae9e112", "type": "concept", "title": "Board and executive oversight"}, {"id": "afba0613-3836-4a96-8502-92814402d2c1", "type": "concept", "title": "HR business partners and centers of excellence"}, {"id": "7cc27842-9565-4615-a5b1-50424bb57b51", "type": "concept", "title": "Policy governance and exception management"}], "description": "Students learn who should decide what in people strategy and how accountability is structured."}, {"id": "80178781-a761-4900-8368-e693aec5fc9c", "type": "subtopic", "title": "Ethical strategic tradeoffs", "children": [{"id": "1c62eac9-e4c0-4c31-92d8-283f88ef2748", "type": "concept", "title": "Layoffs and restructuring"}, {"id": "83b4f325-852a-4e37-b972-96230aaa624f", "type": "concept", "title": "Surveillance and productivity tools"}, {"id": "dc6ff7ac-2276-4d74-9869-0cb4e5251db5", "type": "concept", "title": "Pay, flexibility, and employee voice"}], "description": "The gist is to reason through tensions among cost, performance, wellbeing, fairness, and legal risk."}, {"id": "85897b7f-4aa4-4143-8424-b3a88ae3c6b1", "type": "subtopic", "title": "Stakeholder capitalism and ESG", "children": [{"id": "c3f375d6-9077-49a8-a1bd-26d586ee650d", "type": "concept", "title": "Human capital disclosures"}, {"id": "49253490-7afa-4f8e-8b4a-e9e9de492108", "type": "concept", "title": "Employee wellbeing and safety"}, {"id": "55b53b01-bb2b-48a6-a77a-fbb3064bf65d", "type": "concept", "title": "Community, reputation, and sustainability"}], "description": "Students learn how workforce strategy connects to broader stakeholder value."}, {"id": "9586cd8e-8e1f-4745-a7b0-c66989c42423", "type": "subtopic", "title": "Trust and legitimacy", "children": [{"id": "be481d00-fc45-44de-aa95-026a53465206", "type": "concept", "title": "Transparency and communication"}, {"id": "ec83d659-e81f-4ab6-8add-0ee36035d97f", "type": "concept", "title": "Procedural justice"}, {"id": "65362601-9198-44d9-8a45-0a971d19d250", "type": "concept", "title": "Employee voice and grievance systems"}], "description": "This subtopic focuses on credibility as a strategic asset."}]}], "dbBacked": true}$shrmjson$::jsonb,
  true,
